59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
65	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        HttpHeaders headers = new HttpHeaders();
114	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
115	        String address = normalizeAddress(owner.getAddress());
116	        if (address.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
118	        }
119	        owner.setAddress(address);
120	        if (owner.getEmail() != null) {
121	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
122	            if (!EMAIL_PATTERN.matcher(email).matches()) {
123	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
124	            }
125	            owner.setEmail(email);
126	        }
127	        String telephone = normalizeTelephone(owner.getTelephone());
128	        if (telephone == null) {
129	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
130	        }
131	        owner.setTelephone(telephone);
132	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
133	        owner.setRegistrationDate(registrationDate);
134	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
135	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
136	        }
137	        if (isTelephoneInUse(telephone)) {
138	            return new ResponseEntity<>(HttpStatus.CONFLICT);
139	        }
140	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
141	            return new ResponseEntity<>(HttpStatus.CONFLICT);
142	        }
143	        if (countOwnersInCity(owner.getCity()) >= 50) {
144	            return new ResponseEntity<>(HttpStatus.CONFLICT);
145	        }
146	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
147	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), registrationDate));
148	        owner.setHouseholdId(householdId(owner));
149	        owner.setNamesakeCount(countNamesakes(owner));
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        headers.setLocation(UriComponentsBuilder.newInstance()
153	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
154	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
160	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
161	        if (currentOwner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        currentOwner.setAddress(ownerFieldsDto.getAddress());
165	        currentOwner.setCity(ownerFieldsDto.getCity());
166	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
167	        currentOwner.setLastName(ownerFieldsDto.getLastName());
168	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
169	        String email = ownerFieldsDto.getEmail();
170	        if (email != null) {
171	            email = email.trim().toLowerCase(Locale.ROOT);
172	            if (!EMAIL_PATTERN.matcher(email).matches()) {
173	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	            }
175	        }
176	        currentOwner.setEmail(email);
177	        this.clinicService.saveOwner(currentOwner);
178	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Transactional
183	    @Override
184	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
185	        Owner owner = this.clinicService.findOwnerById(ownerId);
186	        if (owner == null) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        this.clinicService.deleteOwner(owner);
190	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	    }
